import numpy as np
def _digest(a):
    a = np.asarray(a, dtype=float)
    if a.ndim != 2 or a.shape[1] != 4:
        return -1.0
    rows = np.cos(np.arange(1, a.shape[0] + 1))[:, None]
    cols = np.array([1.0, 0.37, 2.11, 5.3])
    return float(np.sum(a * cols * rows) / 10.0 + a.shape[0])
assert np.allclose(_digest(build_loop_tree('((((((((....)))))...))(((..(......)...))))..')), target)

