import numpy as np
def _rows(a, width):
    a = np.asarray(a, dtype=float)
    if a.ndim != 2 or a.shape[1] != width:
        return -1.0
    if a.shape[0] == 0:
        return 0.5
    place = np.cos(np.arange(1, a.shape[0] + 1))[:, None]
    column = np.arange(1, width + 1, dtype=float) if width else np.zeros(0)
    return float(a.shape[0] + np.sum((a + 1.0) * column * place) / 10.0)
assert np.allclose(_rows(enumerate_proper_loop_assignments(2, 1), 1), target)

