import numpy as np
def _tree(db):
    stack = []
    opens = [p for p, s in enumerate(db) if s == '(']
    index = {p: r for r, p in enumerate(opens)}
    k = len(opens)
    t = np.zeros((k + 1, 4), dtype=np.int64)
    t[k] = (-1, len(db), -1, 0)
    owners = [k]
    for p, s in enumerate(db):
        if s == '.':
            t[owners[-1], 3] = 1
        elif s == '(':
            stack.append(p)
            t[index[p], 0] = p
            t[index[p], 2] = owners[-1]
            owners.append(index[p])
        else:
            t[index[stack.pop()], 1] = p
            owners.pop()
    return t
def _poly(a, db):
    width = db.count('(') + 1
    a = np.asarray(a, dtype=float)
    if a.shape != (width,):
        return -1.0
    return float(np.dot(a, np.cos(np.arange(1, width + 1))) / 100.0 + np.sum(a) / 1000.0)
assert np.allclose(_poly(count_level_constrained_designs(_tree('((((((((....)))))...))(((..(......)...))))'), 4, 3, 12), '((((((((....)))))...))(((..(......)...))))'), target)

